function applyDay2ColdRewrite(save, pack) {
  const form = pack.storyForm2 || pack;
  const rw = form.day2ColdRewrites;
  if (!rw || (save.dayIndex||1) < rw.activateOnDayIndexMin) return null;
  if (save.storyFlags?.[rw.applyOnceFlag]) {
    // still ensure WC stays active
  }
  const branch = (rw.branches||[]).find(b => (b.when?.flagsAll||[]).every(f => save.storyFlags?.[f]));
  if (!branch) return null;
  for (const f of branch.setFlagsOnApply||[]) save.storyFlags[f] = true;
  const qs = Quests.ensureQuestSave(save);
  if (!qs.worldActive.includes(branch.worldConsequenceId)) qs.worldActive.push(branch.worldConsequenceId);
  const beat = (form.journalConsequenceBeats||[]).find(j => j.id === branch.journalBeatId);
  if (beat) {
    save.journalConsequenceBeats = save.journalConsequenceBeats || [];
    if (!save.journalConsequenceBeats.some(x => x.id === beat.id)) {
      save.journalConsequenceBeats.unshift({ id: beat.id, day: save.dayIndex, title: beat.title, body: beat.body, repTrack: beat.repTrack });
      save.storyRecap = save.storyRecap || [];
      save.storyRecap.unshift({ day: save.dayIndex, text: /* loc */ beat.title.en + ' — ' + beat.body.en, kind: 'consequence' });
    }
  }
  return branch;
}
